if let Some(last_item) = dict.items.last() {
    // Ex) `**{a: 1, b: 2}`
    let last_value = &last_item.value;
    let value_range = last_value.range();
    let scan_from = match last_item.key.as_ref() {
        Some(key) => key.range().end().max(value_range.end()),
        None => value_range.end(),
    };

    let mut edits = vec![];

    // Delete `**`, any opening parentheses wrapping the dictionary, and
    // the dictionary's opening brace. Comments and whitespace between
    // the tokens are preserved.
    push_deletion(&mut edits, doublestar.range());
    for tok in SimpleTokenizer::starts_at(doublestar.end(), source).skip_trivia() {
        if tok.start() >= dict_start {
            break;
        }
        if matches!(tok.kind(), SimpleTokenKind::LParen) {
            push_deletion(&mut edits, tok.range());
        }
    }
    push_deletion(
        &mut edits,
        TextRange::at(dict_start, TextSize::from(1)),
    );

    // Delete any trailing comma inside the dictionary followed by its
    // closing brace. Then delete any closing parentheses wrapping the
    // dictionary, stopping at the comma that separates the spread from
    // the next item (or at the outer dictionary's closing brace).
    let mut closing_brace_deleted = false;
    for tok in SimpleTokenizer::starts_at(scan_from, source).skip_trivia() {
        match tok.kind() {
            SimpleTokenKind::Comma if !closing_brace_deleted => {
                push_deletion(&mut edits, tok.range());
            }
            SimpleTokenKind::RBrace if !closing_brace_deleted => {
                push_deletion(&mut edits, tok.range());
                closing_brace_deleted = true;
            }
            SimpleTokenKind::RParen if closing_brace_deleted => {
                push_deletion(&mut edits, tok.range());
            }
            _ if closing_brace_deleted => break,
            _ => {}
        }
    }

    Some(Fix::safe_edits(
        // Delete the first `**{`
        Edit::deletion(doublestar.start(), dict_start + TextSize::from(1)),
        // Delete the trailing `}`
        edits,
    ))
} else {
    // Ex) `**{}`
    Some(Fix::safe_edit(Edit::deletion(doublestar.start(), dict_end)))
}

